/* Puff · 樱桃粉白线下完整默认（最终整合优化版 - 舒适阅读&精致细节） */

/* ========== A. 列表入口变量（主页） ========== */

.off-app {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-71284363-d072-463f-9398-844b6a068d88.jpg');

  background-size: cover;

  background-position: center;

  background-color: #FFF5F8;

  --off-list-radius: 0px !important; 

}

html[data-theme="dark"] .off-app {

  --off-list-bg: rgba(60, 15, 25, 0.85);

  --off-list-border: rgba(255, 150, 170, 0.4);

}

/* ========== B. 列表顶栏 / 筛选（加内凹实体按键感） ========== */

.off-inbox-top {

  background: linear-gradient(180deg, rgba(255, 245, 248, 0.95), rgba(255, 245, 248, 0.7));

  backdrop-filter: blur(15px) saturate(160%);

  -webkit-backdrop-filter: blur(15px) saturate(160%);

  border-bottom: 1px solid #FFD1DC;

}

.off-inbox-filter button {

  border-radius: 12px;

  margin: 0 4px;

  color: #B56A7D;

  background: rgba(255, 255, 255, 0.5);

  border: 1px solid rgba(255, 255, 255, 0.8);

  transition: all 0.2s;

}

.off-inbox-filter button.on {

  background: #C76A7E;

  color: #FFFFFF;

  border-color: #FFFFFF;

  /* 改为按压内凹的实体手感 */

  box-shadow: inset 2px 2px 4px rgba(168, 0, 34, 0.5), inset -2px -2px 4px #FFFFFF;

}

/* ========== C. 入口列表行（保持原有的半透果冻+双线框） ========== */

.off-list-btn {

  background: linear-gradient(135deg, rgba(255, 255, 255, 0.75), rgba(255, 230, 235, 0.45)) !important;

  border: 2px solid #FFD1DC !important;

  border-radius: 0px !important;



  padding: 10px 14px !important;

  margin-bottom: 12px !important;



  box-shadow: 4px 4px 10px rgba(255, 150, 170, 0.35), -4px -4px 10px rgba(255, 255, 255, 0.9) !important;

  transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);

}

.off-list-btn:hover { transform: translateY(-3px); }

.off-list-btn:active { transform: translateY(1px); box-shadow: inset 4px 4px 8px rgba(255, 182, 193, 0.5), inset -4px -4px 8px #FFFFFF !important; }

.off-list-ava {

  width: 40px !important;

  height: 40px !important;

  border-radius: 0px !important;

  border: 2px solid #FFFFFF !important;

  box-shadow: 0 0 0 2px #FFD1DC !important;

}

.off-list-body strong {

  font-size: 15px !important;

  color: #B56A7D;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  font-weight: 700;

}

.off-list-body span {

  font-size: 12px !important;

  color: #D0A5AE;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

  opacity: 0.9;

}

.off-list-go { color: #D9859A; }

.off-list-go.is-new { background: #C76A7E; border-radius: 0px; color: #FFF; }

/* ========== D. 当面共处主题变量 ========== */

.off-app.off-app-session {

  --off-card-user: #FFFFFF;

  --off-card-peer: #FFF5F8;

  --off-card-border: #FFD1DC;

  --off-card-shadow: 0 8px 20px rgba(255, 150, 170, 0.3);

  --off-dock-bg: rgba(255, 255, 255, 0.95);

  color: #C76A7E;

}

.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-6c690a7b-8d0d-48ca-a3b3-dc834593b1b7.jpg');

  background-size: cover;

  background-position: center;

  background-color: #FFEFF3; 

}

/* ========== E. 当面顶栏 ========== */

.off-app.off-app-session .off-stage-head {

  border-bottom: 2px solid #FFD1DC;

  background: rgba(255, 250, 252, 0.9);

}

.off-app.off-app-session .off-stage-scene {

  font-weight: 600;

  letter-spacing: 0.04em;

  color: #B56A7D;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

.off-app.off-app-session .off-stage-peer-text strong {

  color: #C76A7E;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

.off-stage-ava {

  border-radius: 0px !important;

  border: 2px solid #FFFFFF;

  box-shadow: 0 0 0 2px #FFD1DC;

}

/* ========== F. 幕间分割线（极浅半透明，保留原有效果） ========== */

.off-act-divider {

  display: flex;

  justify-content: center;

  align-items: center;

  gap: 6px;

  margin: 8px 0;

}

.off-act-divider span {

  background: rgba(255, 255, 255, 0.35);

  border: 1px solid rgba(255, 255, 255, 0.6);

  border-radius: 999px !important;

  padding: 3px 10px !important;

  color: #B56A7D;

  font-size: 11px !important;

  font-weight: 700;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

.off-act-divider i {

  background: rgba(255, 220, 230, 0.45);

  border: 1px solid rgba(255, 255, 255, 0.6);

  border-radius: 999px !important;

  padding: 3px 10px !important;

  color: #C76A7E;

  font-size: 11px !important;

  font-weight: 700;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

/* ========== G. 日记卡片（软透玻璃，舒服不刺眼） ========== */

.off-app.off-app-session .off-passage-sheet {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-554e7fdc-c4f6-40e5-ae3e-72f47c790f2f.jpg');

  background-size: cover;

  background-position: center;

  background-color: rgba(255, 240, 245, 0.88); 

  background-blend-mode: lighten;

  border: 2px dashed #FFD1DC; 

  outline: 2px dashed #FFFFFF;

  outline-offset: -6px;

  border-radius: 0px;

  box-shadow: 0 8px 20px rgba(255, 150, 170, 0.25);

}

.off-app.off-app-session .off-passage.is-me .off-passage-sheet {

  background-color: rgba(255, 220, 230, 0.92);

  border: 2px dashed #FFD1DC; 

  outline: 2px dashed #FFFFFF;

}

/* ========== H. 正文排版（优化字间距，更舒服） ========== */

.off-app.off-app-session .off-prose-para,

.off-app.off-app-session .off-prose-narr,

.off-app.off-app-session .off-prose-plain {

  font-family: var(--off-prose-narr-font, var(--off-prose-font));

  line-height: 1.9; /* 提高行高，更透气 */

  letter-spacing: 0.02em;

  font-size: var(--off-prose-narr-size, 14.5px);

  color: #C08B9A; /* 颜色继续调浅，更温柔 */

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

.off-app.off-app-session .off-prose-dial {

  line-height: 1.9;

  letter-spacing: 0.02em;

  color: #B56A7D;

  font-weight: 600;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff;

}

.off-app.off-app-session .off-prose-para em,

.off-app.off-app-session .off-prose-para i { color: #F2B3C1; font-style: italic; }

.off-app.off-app-session .off-prose-para strong,

.off-app.off-app-session .off-prose-para b { color: #8A2038; font-weight: 700; }

.off-app.off-app-session blockquote { color: #7A1B2E; border-left: 2px solid #F2B3C1; padding-left: 8px; }

.off-app.off-app-session .off-prose-tr { font-size: 12px; opacity: 0.8; }

/* ========== I. 底部提示条（美化"暂离现场"样式） ========== */

.off-app.off-app-session .off-stage-tip, 

.off-app.off-app-session .off-stage-alert {

  background: rgba(255, 255, 255, 0.75);

  border: 1px solid #FFD1DC;

  border-radius: 12px;

  color: #B56A7D;

  box-shadow: 0 4px 12px rgba(255, 182, 193, 0.3);

  font-weight: 600;

}

/* ========== J. 底栏输入框（完美保留你的樱桃按钮） ========== */

.off-app.off-app-session .off-stage-dock {

  background: rgba(255, 240, 243, 0.95);

  border-top: 2px solid #FFD1DC;

}

.off-compose-bar {

  background: rgba(255, 255, 255, 0.95);

  border: 2px dashed #FFD1DC !important;

  outline: 2px dashed #FFFFFF !important;

  outline-offset: -5px;

  border-radius: 0px !important;

}

.off-app.off-app-session .off-compose-input {

  color: #B56A7D;

}

.off-compose-send {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-2e4a592f-a4aa-44df-990c-4e5c39e512bd.png') !important;

  background-size: cover;

  background-position: center;

  background-repeat: no-repeat;

  background-color: transparent !important;

  border: none !important;

  border-radius: 0px !important;

  /* 加一层粉色高光晕，让按钮更突出 */

  box-shadow: 0 0 8px rgba(255, 150, 170, 0.8);

  transition: transform 0.1s;

}

.off-compose-send:active { transform: scale(0.95); }

/* 模块 1：物理按压/悬浮反馈 */

.off-list-btn, .off-compose-bar, .off-tool-btn {

    transition: transform 0.15s ease, box-shadow 0.15s ease;

}

.off-list-btn:hover, .off-tool-btn:hover {

    transform: translateY(-2px);

    box-shadow: 4px 6px 12px rgba(255, 150, 170, 0.5), -4px -4px 12px rgba(255, 255, 255, 1);

}

.off-list-btn:active, .off-tool-btn:active, .off-compose-send:active {

    transform: translateY(1px) scale(0.98);

    box-shadow: inset 3px 3px 6px rgba(255, 150, 170, 0.6), inset -3px -3px 6px rgba(255, 255, 255, 1);

}

/* 模块 4：果冻胶囊按钮 */

.off-act-divider span, .off-act-divider i {

    background: linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(255, 235, 240, 0.3));

    border: 1px solid rgba(255, 255, 255, 0.9);

    box-shadow: 

        inset 0 2px 4px rgba(255, 255, 255, 1), 

        inset 0 -2px 4px rgba(255, 182, 193, 0.4), 

        0 4px 8px rgba(255, 150, 170, 0.2);

}

.off-inbox-filter button.on {

    background: #FF8DA1;

    box-shadow: inset 2px 2px 6px rgba(200, 30, 60, 0.6), inset -2px -2px 6px rgba(255, 255, 255, 0.6);

}

/* 模块 6：液态果冻输入框 */

.off-compose-bar {

    background: linear-gradient(180deg, rgba(255, 240, 245, 0.7), rgba(255, 255, 255, 0.4)) !important;

    border: 1px solid rgba(255, 255, 255, 0.9) !important;

    border-radius: 8px !important;

    outline: 1px dashed rgba(255, 182, 193, 0.6) !important;

    outline-offset: -6px;

    box-shadow: 

        inset 2px 2px 8px rgba(255, 182, 193, 0.4), 

        inset -2px -2px 8px rgba(255, 255, 255, 1), 

        0 8px 16px rgba(255, 150, 170, 0.2);

}

/* 模块 8：输入框微光 */

.off-compose-input::placeholder {

    color: #F3D6DB !important;

}

.off-compose-send {

    box-shadow: 0 0 12px rgba(255, 150, 170, 0.8), 0 0 24px rgba(255, 182, 193, 0.4) !important;

}

.off-compose-send:active {

    box-shadow: 0 0 6px rgba(255, 150, 170, 0.8), inset 2px 2px 4px rgba(255, 182, 193, 0.6) !important;

}

/* 模块 B：头像相框与名字发光 */

.off-app.off-app-session .off-stage-ava {

    border-radius: 0px !important;

    border: 3px dashed #FFFFFF !important;

    outline: 3px dashed #FFB6C1 !important;

    outline-offset: -6px;

    box-shadow: 4px 4px 10px rgba(255, 150, 170, 0.4) !important;

}

.off-app.off-app-session .off-stage-peer-text strong {

    font-weight: 700;

    color: #B56A7D;

    text-shadow: 0 0 4px #FFF, 0 0 8px #FFEFF3, -1px -1px 0 #fff, 1px -1px 0 #fff !important;

}

.off-app.off-app-session .off-stage-peer-text {

    letter-spacing: 0.02em;

}

/* 模块 C：第一幕/时间邮票胶囊 */

.off-act-divider span,

.off-act-divider i {

    background: linear-gradient(145deg, #FFFFFF, #FFEEF2) !important;

    border: 2px dashed #FFB6C1 !important;

    border-radius: 99px !important;

    box-shadow: 

        inset 2px 2px 4px #FFF, 

        inset -2px -2px 4px #FFD1DC, 

        4px 4px 8px rgba(255, 150, 170, 0.3), 

        -2px -2px 8px #FFFFFF !important;

    color: #B56A7D !important;

    font-weight: 700;

    letter-spacing: 0.04em;

}

/* 纯白虚线外圈轻轻包围，提升层次感 */

.off-act-divider::before {

    content: '';

    position: absolute;

    left: 50%;

    transform: translateX(-50%);

    width: 80%;

    height: 1px;

    background: rgba(255, 182, 193, 0.5);

    z-index: -1;

}

/* ========== 模块 H：极简清爽轻玻璃（完美移除方框底托） ========== */

/* 1. 顶部背景：5px四分之一模糊轻玻璃 */

.off-app.off-app-session .off-stage-head {

    background: rgba(255, 240, 245, 0.45) !important;

    backdrop-filter: blur(5px) saturate(130%) !important;

    -webkit-backdrop-filter: blur(5px) saturate(130%) !important;

    border-bottom: 1px solid rgba(255, 209, 220, 0.8) !important;

    box-shadow: none !important;

}

/* 2. 强行移除所有多余的白色方块！让文字直接浮在玻璃上 */

.off-app.off-app-session .off-stage-head div,

.off-app.off-app-session .off-stage-head strong,

.off-app.off-app-session .off-stage-scene,

.off-app.off-app-session .off-stage-peer-text strong {

    background: transparent !important;

    padding: 0 !important;

    border-radius: 0 !important;

    display: inline !important;

}

/* 3. 文字：用细腻的双层白描边防糊，绝不加背景块 */

.off-app.off-app-session .off-stage-head,

.off-app.off-app-session .off-stage-head * {

    text-shadow: 

        -1px -1px 0 #fff, 1px -1px 0 #fff, 

        -1px 1px 0 #fff, 1px 1px 0 #fff,

        0 2px 3px rgba(255, 255, 255, 0.8) !important;

    color: #A34D5E !important;

    font-weight: 700 !important;

}

/* 4. 右侧按钮保持实体不透明，完全清晰可点 */

.off-app.off-app-session .off-stage-head button {

    text-shadow: none !important;

}

.off-app.off-app-session .off-stage-head button:not(:last-child) {

    background: #FFFFFF !important;

    color: #C9184A !important;

    border: 1px solid #FFD1DC !important;

    border-radius: 999px !important;

    box-shadow: 2px 2px 6px rgba(255, 182, 193, 0.3) !important;

}

.off-app.off-app-session .off-stage-head button:last-child {

    background: #C9184A !important;

    color: #FFFFFF !important;

    border: none !important;

    border-radius: 999px !important;

    box-shadow: 2px 2px 6px rgba(201, 24, 74, 0.4) !important;

}

/* 模块 2：输入框聚焦光环 */

.off-compose-bar:focus-within {

    border: 2px solid #FF8DA1 !important;

    box-shadow: 0 0 0 4px rgba(255, 141, 161, 0.3), 0 0 12px rgba(255, 141, 161, 0.6) !important;

    transition: all 0.3s ease;

}

/* 模块 4：实体按钮水波纹 */

@keyframes ripple {

    from { transform: scale(0); opacity: 0.8; }

    to { transform: scale(2.5); opacity: 0; }

}

.off-compose-send, 

.off-app.off-app-session .off-stage-head button {

    position: relative;

    overflow: hidden;

}

.off-compose-send::after, 

.off-app.off-app-session .off-stage-head button::after {

    content: '';

    position: absolute;

    inset: 0;

    border-radius: 50%;

    background: rgba(255, 255, 255, 0.6);

    transform: scale(0);

    opacity: 0;

    pointer-events: none;

}

.off-compose-send:active::after, 

.off-app.off-app-session .off-stage-head button:active::after {

    animation: ripple 0.4s ease-out;

}

/* 模块 7：第一页主卡片水晶质感 */

.off-list-btn {

    background: linear-gradient(145deg, rgba(255, 255, 255, 0.75), rgba(255, 240, 245, 0.5)) !important;

    border: 1px solid rgba(255, 255, 255, 0.9) !important;

    border-radius: 12px !important; /* 稍微加一点圆角显高级 */

    box-shadow: 

        -4px -4px 10px rgba(255, 255, 255, 0.9),   /* 左上冷白光 */

        6px 6px 16px rgba(255, 170, 190, 0.5),     /* 右下暖粉阴影 */

        inset 0 0 0 1px rgba(255, 209, 220, 0.4) !important; /* 内部细粉线 */

}

/* 头像像嵌在玻璃里的相框 */

.off-list-ava {

    border-radius: 8px !important;

    box-shadow: 

        0 0 0 2px #FFF, 

        0 4px 8px rgba(0, 0, 0, 0.1), 

        inset 2px 2px 4px rgba(255, 255, 255, 0.8) !important;

}

/* 右侧箭头做成"拆分线"按钮，高级排版 */

.off-list-go {

    border-left: 1px solid rgba(255, 209, 220, 0.6);

    margin-left: 8px;

    padding-left: 12px;

    color: #D9859A;

    transition: transform 0.2s;

}

.off-list-btn:hover .off-list-go {

    transform: translateX(3px);

}
